#include <cstddef>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

template <typename T>
class Box {                                    // a small bag of T values.
public:
    Box() = default;
    explicit Box(T first) { items_.push_back(std::move(first)); }

    void add(T value) { items_.push_back(std::move(value)); }
    std::size_t size() const { return items_.size(); }
    const T& at(std::size_t i) const { return items_.at(i); }   // throws if out of range.
    const T& largest() const {                 // only instantiated if called: needs <.
        if (items_.empty()) throw std::logic_error("empty box");
        const T* best = &items_[0];
        for (const T& v : items_) if (*best < v) best = &v;
        return *best;
    }
private:
    std::vector<T> items_;                     // value semantics: copies with the Box.
};

int main() {
    Box<int> numbers{42};                      // Box<int>.
    Box words{std::string("hi")};             // deduced: Box<std::string>.
    Box<int> copy = numbers;                   // independent copy.
    copy.add(7);                               // numbers.size() is still 1.
}
